def _resolve_workplan_groups(plan) -> list:
    """Return the groups list from plan.workplan or plan.strategy.parallelisable_workplan."""
    workplan = getattr(plan, 'workplan', None)
    if not workplan:
        strategy = getattr(plan, 'strategy', None)
        if strategy:
            workplan = getattr(strategy, 'parallelisable_workplan', None)
    return getattr(workplan, 'groups', []) if workplan else []


def _collect_tasks(groups) -> list:
    """Flatten tasks from all groups."""
    tasks = []
    for group in groups or []:
        tasks.extend(getattr(group, 'tasks', []) or [])
    return tasks


def _check_task_file_invariants(tasks, violations):
    """Check that each task has exactly 1 file and no file collisions."""
    seen: set[str] = set()
    for task in tasks:
        fps = getattr(task, 'file_paths', None) or []
        if len(fps) != 1:
            violations.append(f"task {getattr(task, 'id', '?')} lists {len(fps)} files (exactly 1 required)")
        for fp in fps:
            if fp in seen:
                violations.append(f'file collision: {fp} in multiple tasks')
